create table public.customer_profiles (id uuid primary key default gen_random_uuid(), user_id uuid not null unique references public.users(id) on delete cascade, marketing_consent_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.customer_addresses (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.users(id) on delete cascade, recipient_name text not null, phone text, address_line1 text not null, address_line2 text, locality text not null, city text not null, region text not null, postal_code text not null, country_code char(2) not null default 'IN', is_default boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create unique index uq_customer_default_address on public.customer_addresses(user_id) where is_default;
